  "player_descriptions": {
    "2": "Lional, what a performance, netting a hat-trick and setting up even more! Your shots were a constant threat, and your accuracy in front of goal was on point as your team cruised to victory. You were a key reason for the team's success!",
    "7": "Tarun, you kept the pressure high, even though the goals didn't come this time. Your positioning was excellent, creating several opportunities for yourself, you'll definitely find the net next game!",
    "1": "Alinga, you were a vital part of the attack, linking up well and providing an assist in the big win. Keep making those key passes and the goals will come. Your work rate was immense!",
    "4": "Jaltan, that was a fantastic goal! Your dribbling skills really shone through, and you contributed defensively as well, helping your team secure the win. Keep up the great work!",
    "9": "Hareesh, four goals is an absolutely stunning return, well done! Your finishing was clinical, and you also created chances for your teammates. It's no wonder your team won so convincingly.",
    "6": "Kavin, you had a good game, scoring a goal and making some crucial saves. You played with great versatility and contributed at both ends of the pitch! That's what a good team player looks like.",
    "3": "Prateek, you were a rock in midfield, breaking up plays and protecting the defense in this big win. You made some important interceptions. Keep up that solid defensive work!",
    "5": "Mahadhona, you were instrumental in creating attacking opportunities, providing a great assist. Your movement off the ball was excellent. Well played!",
    "10": "Dev, you were unbeatable in goal, with an incredible number of saves. You even scored a goal yourself! What a performance and a clean sheet!",
    "11": "Kalyan, you were lethal in front of goal, scoring four goals! Your determination to get on the scoresheet really paid off. That kind of firepower makes all the difference in a victory!",
    "14": "Juhu, you got yourself a goal, which is fantastic! You were a threat going forward and put in a solid defensive shift too. You really helped the team secure that win!",
    "12": "Rohan, you found the back of the net, well done! You made a great impact on the game. That kind of contribution is always appreciated in a strong team performance!",
    "13": "Jamla, your defensive work and determination was key today. While your shot didn't find the net, you were still kept up the pressure. Keep putting in that effort!"
  },
  "match_description": "What a day for Street Legends, securing a dominant 12-4 victory over Ballers for Life! Jaltan Ibrahimi drew first blood for Ballers for Life, but that merely stirred the beast within Street Legends as Hareesh Khan responded quickly and ruthlessly, bagging four goals in a stunning display, closely followed by Kalyan Mbappi who also managed to secure four goals. Lional Masi chipped in with a hat trick of his own to complete a dominant attacking display. Despite Dev Digia's best efforts to spark a comeback for Ballers for Life, Street Legends proved unstoppable today!",
